static void rtDraw(){u8g2.setFont(FONT_S);textC("REACTION TEST",7);u8g2.drawFrame(12,14,104,34);u8g2.setFont(FONT_M);if(rtState==0)textC("WAIT...",35);else if(rtState==1)textC("PRESS!",35);else if(rtState==2){char b[20];snprintf(b,sizeof b,"%lu ms",(unsigned long)rtDelay);textC(b,35);u8g2.setFont(FONT_S);char c[20];snprintf(c,sizeof c,"BEST %u ms",rtBest);textC(c,59);}else textC("TOO EARLY!",35);}
static void rtIcon(int x,int y){u8g2.drawCircle(x+16,y+16,12);u8g2.drawLine(x+16,y+16,x+16,y+7);u8g2.drawLine(x+16,y+16,x+23,y+20);u8g2.drawDisc(x+16,y+16,2);}

