// ARCADE - multi-game console for ESP32-S3 N16R8 + 2.4in ST7789 SPI TFT
// Libraries: U8g2, Adafruit GFX Library, Adafruit ST7735 and ST7789 Library. Board: ESP32S3 Dev Module.
// Pins / options: config.h.  Add games: games.h.
//
// CONTROLS
//   Stick       move / navigate           A  = main action (select, jump, fire...)
//   B           secondary (duck, bomb...)  Stick click (SW) = PAUSE MENU (resume / restart / sound / quit)
//   Screen brightness is adjusted in Settings; touch and RGB LED are disabled.
#include "hal.h"
#include "games.h"

enum Mode : uint8_t { MODE_MENU, MODE_INTRO, MODE_PLAY, MODE_PAUSE };
static Mode     mode = MODE_MENU;
static uint8_t  sel = 0, cur = 0, pauseSel = 0;
static uint32_t menuLock = 0;       // ignore input briefly after entering the menu (no accidental launch)
static int16_t  menuTarget = 0;      // unbounded card index so wrap-around animates smoothly
static float    menuPos = 0;         // animated position (card units)
static uint16_t hiCache[40];

static void enterMenu() {
  mode = MODE_MENU; audioStop(); bannerUntil = 0; toastUntil = 0; gotoMenu = false; ledFlashEnd = 0; overAt = 0;
  sel = cur; menuTarget = sel; menuPos = sel; menuLock = millis() + 200;
  for (uint8_t i = 0; i < NGAMES && i < 40; i++) hiCache[i] = GAMES[i].kind ? 0 : hiGet(i);
  ledSetBase(GAMES[sel].r, GAMES[sel].g, GAMES[sel].b);
}
static void startGame(uint8_t i) {
  cur = i; mode = MODE_PLAY; bannerUntil = 0; toastUntil = 0; gotoMenu = false;
  ledSetBase(GAMES[i].r, GAMES[i].g, GAMES[i].b);
  GAMES[i].init(); fx(SFX_START, C_WHITE, 150);
}

// ------------------------------------------------------------------ launcher
static void menuInput() {
  if ((int32_t)(millis() - menuLock) < 0) return;
  int8_t d = in.rx ? in.rx : in.ry;
  if (d) {
    menuTarget += d; sel = ((menuTarget % NGAMES) + NGAMES) % NGAMES; sfx(SFX_MOVE);
    ledSetBase(GAMES[sel].r, GAMES[sel].g, GAMES[sel].b);
  }
  if (in.aP || in.swP) {
    sfx(SFX_SELECT);
    if (GAMES[sel].kind) startGame(sel); else { cur = sel; mode = MODE_INTRO; }
  }
}
static void menuCard(int cx, int y, uint8_t g, float near) {   // near: 1 = selected .. 0 = side card
  int x = cx - 18;
  if (near > 0.6f) {
    u8g2.drawRFrame(x, y, 36, 36, 3);
    if ((millis() / 400) & 1) u8g2.drawRFrame(x - 1, y - 1, 38, 38, 4);    // blinking selection halo
    GAMES[g].icon(x + 2, y + 2);
  } else {
    u8g2.drawRFrame(x + 2, y + 2, 32, 32, 3); GAMES[g].icon(x + 2, y + 2);
    u8g2.setDrawColor(0);   // dim side cards with a checker mask
    for (int j = 0; j < 36; j += 2) for (int i = (j >> 1) & 1; i < 36; i += 2) u8g2.drawPixel(x + i, y + j);
    u8g2.setDrawColor(1);
  }
}
static void menuDraw() {
  if (!ledFlashEnd) {
    float k = 0.45f + 0.55f * (0.5f + 0.5f * sinf(millis() / 350.0f));
    ledApply((uint8_t)(GAMES[sel].r * k), (uint8_t)(GAMES[sel].g * k), (uint8_t)(GAMES[sel].b * k));
  }
  menuPos += (menuTarget - menuPos) * 0.38f; if (fabsf(menuTarget - menuPos) < 0.02f) menuPos = menuTarget;
  char b[16];
  u8g2.setFont(FONT_S); u8g2.setDrawColor(1); u8g2.drawBox(0, 0, 128, 9); u8g2.setDrawColor(0);
  u8g2.drawStr(2, 7, "ARCADE"); snprintf(b, sizeof b, "%u/%u", sel + 1, NGAMES); u8g2.drawStr(64 - u8g2.getStrWidth(b) / 2, 7, b);
  if (hiCache[sel]) { snprintf(b, sizeof b, "HI %u", hiCache[sel]); u8g2.drawStr(126 - 14 - u8g2.getStrWidth(b) - 4, 7, b); }
  drawSpeaker(117, 1, cfg.sound); u8g2.setDrawColor(1);
  int base = (int)floorf(menuPos);
  for (int i = base - 1; i <= base + 2; i++) {
    float d = i - menuPos, ad = fabsf(d);
    if (ad > 1.7f) continue;
    uint8_t g = ((i % NGAMES) + NGAMES) % NGAMES;
    menuCard(64 + (int)(d * 46), 11 + (ad > 1 ? 3 : (int)(ad * 3)), g, ad < 0.5f ? 1.0f : 0.0f);
  }
  u8g2.setFont(FONT_M); textC(GAMES[sel].name, 55);
  u8g2.setFont(FONT_S); textC(GAME_DESC[sel], 63);
}

// ------------------------------------------------------------------ intro card (controls)
static void introInput() {
  if (in.bP) { sfx(SFX_BACK); enterMenu(); }
  else if (in.aP || in.swP) startGame(cur);
}
static void introDraw() {
  const Game& g = GAMES[cur];
  u8g2.setDrawColor(1); u8g2.drawBox(0, 0, 128, 11); u8g2.setDrawColor(0); u8g2.setFont(FONT_M); textC(g.name, 9); u8g2.setDrawColor(1);
  u8g2.drawFrame(2, 14, 36, 36); g.icon(4, 16);
  u8g2.setFont(FONT_S);
  u8g2.drawStr(42, 22, g.help1); u8g2.drawStr(42, 31, g.help2); u8g2.drawStr(42, 40, "SW: pause menu");
  char b[16]; snprintf(b, sizeof b, "BEST %u", hiCache[cur]); u8g2.drawStr(42, 49, b);
  u8g2.drawHLine(0, 53, 128); u8g2.drawStr(2, 62, "A:START"); u8g2.drawStr(128 - 7 * 5 - 2, 62, "B:BACK");
}

// ------------------------------------------------------------------ play + pause
static void playInput() {
  if (GAMES[cur].kind) { if (in.swP || gotoMenu) { gotoMenu = false; sfx(SFX_BACK); enterMenu(); } else GAMES[cur].update(); return; }
  if (in.swP) { mode = MODE_PAUSE; pauseSel = 0; audioStop(); sfx(SFX_SELECT); return; }
  if (gotoMenu) { gotoMenu = false; sfx(SFX_BACK); enterMenu(); return; }
  GAMES[cur].update();
}
static void pauseInput() {
  if (in.py < 0) { pauseSel = (pauseSel + 3) % 4; sfx(SFX_MOVE); }
  if (in.py > 0) { pauseSel = (pauseSel + 1) % 4; sfx(SFX_MOVE); }
  if (in.bP) { mode = MODE_PLAY; sfx(SFX_BACK); return; }
  if (!in.aP && !in.swP) return;                // A or stick-click confirms the highlighted item
  switch (pauseSel) {
    case 0: mode = MODE_PLAY; sfx(SFX_BACK); break;
    case 1: GAMES[cur].init(); mode = MODE_PLAY; fx(SFX_START, C_WHITE, 150); break;
    case 2: cfg.sound = !cfg.sound; cfgSave(); if (!cfg.sound) audioStop(); else sfx(SFX_SELECT); break;
    default: sfx(SFX_BACK); enterMenu();
  }
}
static void pauseDraw() {
  u8g2.setDrawColor(0); u8g2.drawBox(22, 4, 84, 57); u8g2.setDrawColor(1); u8g2.drawFrame(22, 4, 84, 57);
  u8g2.setFont(FONT_M); textC("PAUSED", 15); u8g2.setFont(FONT_S);
  const char* it[4] = {"Resume", "Restart", cfg.sound ? "Sound: ON" : "Sound: OFF", "Quit to menu"};
  for (uint8_t i = 0; i < 4; i++) {
    int y = 27 + i * 9; bool on = (i == pauseSel);
    if (on) u8g2.drawBox(26, y - 7, 76, 9);
    u8g2.setDrawColor(on ? 0 : 1); u8g2.drawStr(30, y, it[i]); u8g2.setDrawColor(1);
  }
}

// ------------------------------------------------------------------ boot
// scaled gamepad logo (s = 0..1.3), centred at cx,cy
static void bootLogo(int cx, int cy, float s) {
  int w = (int)(26 * s), h = (int)(14 * s); if (w < 2) return;
  u8g2.drawRBox(cx - w, cy - h, w * 2, h * 2, imax(1, (int)(5 * s)));
  u8g2.setDrawColor(0);
  int px = cx - w * 5 / 8, dp = imax(1, (int)(2 * s));                  // d-pad
  u8g2.drawBox(px - dp * 2, cy - dp / 2, dp * 4 + 1, dp); u8g2.drawBox(px - dp / 2, cy - dp * 2, dp, dp * 4 + 1);
  u8g2.drawDisc(cx + w / 2, cy - h / 4, imax(1, (int)(2 * s))); u8g2.drawDisc(cx + w * 3 / 4, cy + h / 5, imax(1, (int)(2 * s)));
  u8g2.drawBox(cx - w / 4, cy + h / 3, imax(1, w / 5), imax(1, dp / 2)); u8g2.drawBox(cx, cy + h / 3, imax(1, w / 5), imax(1, dp / 2));
  u8g2.setDrawColor(1);
}
static void bootShutter(uint32_t ms, bool open, bool menu) {   // black bars close (logo) or open (menu) from the middle
  uint32_t t0 = millis();
  for (;;) {
    uint32_t e = millis() - t0; if (e >= ms) break;
    int w = (int)(64L * e / ms); if (open) w = 64 - w;
    u8g2.clearBuffer();
    if (menu) menuDraw(); else { bootLogo(64, 24, 1.0f); u8g2.setFont(FONT_M); textC("ARCADE", 52); }
    u8g2.setDrawColor(0);
    if (menu) { u8g2.drawBox(0, 0, w, 64); u8g2.drawBox(128 - w, 0, w, 64); }          // curtains parting toward the edges
    else { u8g2.drawBox(0, 0, 128, w / 2); u8g2.drawBox(0, 64 - w / 2, 128, w / 2); }   // lids closing on the logo
    u8g2.setDrawColor(1); u8g2.sendBuffer(); audioUpdate();
  }
}
void setup() {
  cfgLoad(); randomSeed(esp_random());
  displayInit(); u8g2.setBrightness(SCREEN_BRIGHTNESS[cfg.led]); inputInit(); audioInit();
  ledApply(0, 0, 0); sfx(SFX_BOOT);
  static uint8_t pX[14], pY[14], pS[14];                       // sparkle particles
  for (uint8_t i = 0; i < 14; i++) { pX[i] = random(128); pY[i] = random(64); pS[i] = 1 + random(3); }
  const uint32_t T = 1700; uint32_t t0 = millis(), e;
  while ((e = millis() - t0) < T) {
    u8g2.clearBuffer();
    for (uint8_t i = 0; i < 14; i++) {                         // particles drift up, twinkle
      pY[i] = (pY[i] + 64 - pS[i] / 2) & 63; if (((e / 90) + i) % 3) u8g2.drawPixel(pX[i], pY[i]);
    }
    float p = e / 650.0f; if (p > 1) p = 1;                     // ease-out-back pop-in
    float q = p - 1, s = 1 + 2.70158f * q * q * q + 1.70158f * q * q;
    int cy = 24, r = (int)(16 + 30 * (e / (float)T));           // expanding dotted glow ring
    if (e > 150) for (int a = 0; a < 48; a += 1) if (((a + e / 40) & 3) == 0) {
      float an = a * 0.1309f; int x = 64 + (int)(cosf(an) * r * 1.6f), y = cy + (int)(sinf(an) * r); if (x >= 0 && x < 128 && y >= 0 && y < 64) u8g2.drawPixel(x, y);
    }
    bootLogo(64, cy, s);
    if (e > 600) {                                               // wordmark pops in with stepped font sizes
      u8g2.setFont(e < 700 ? u8g2_font_6x10_tf : (e < 800 ? u8g2_font_helvB10_tf : u8g2_font_helvB14_tf)); textC("ARCADE", e < 700 ? 50 : (e < 800 ? 52 : 56));
    }
    if (e > 1000) { u8g2.setFont(FONT_S); textC("ESP32-S3 GAME CONSOLE", 63); }
    int sy = (int)((e * 3) % 190) - 30;                          // scanline sweep with dither trail
    if (sy >= 0 && sy < 64) { u8g2.setDrawColor(2); u8g2.drawHLine(0, sy, 128); u8g2.setDrawColor(1); for (int x = sy & 1; x < 128; x += 2) if (sy > 2) u8g2.drawPixel(x, sy - 2); }
    u8g2.sendBuffer();
    uint8_t k = (uint8_t)(220 * (e < 650 ? e / 650.0f : 1.0f - (e - 650) / (float)(T - 650) * 0.6f)); ledApply(k / 3, k / 2, k);
    audioUpdate();
  }
  bootShutter(220, false, false);
  ledApply(0, 0, 0); enterMenu();
  bootShutter(300, true, true);
}

void loop() {
  uint32_t t0 = millis();
  inputUpdate(); audioUpdate(); ledUpdate();
  if (in.touchP) {
    cfg.sound = !cfg.sound; cfgSave();
    if (!cfg.sound) audioStop(); else sfx(SFX_SELECT);
    toast(cfg.sound ? "SOUND ON" : "SOUND OFF");
  }
  switch (mode) {
    case MODE_MENU:  menuInput();  break;
    case MODE_INTRO: introInput(); break;
    case MODE_PLAY:  playInput();  break;
    default:         pauseInput();
  }
  u8g2.clearBuffer();
  switch (mode) {
    case MODE_MENU:  menuDraw();  break;
    case MODE_INTRO: introDraw(); break;
    case MODE_PLAY:  GAMES[cur].draw(); break;
    default:         GAMES[cur].draw(); pauseDraw();
  }
  toastDraw(); bannerDraw();
  u8g2.sendBuffer();
  while (millis() - t0 < FRAME_MS) delay(1);
}

#pragma once
// Temple Dash - endless runner, 3 lanes seen from behind. Stick left/right = change lane, A = jump (low barriers),
// B = slide (overhead beams), walls must be dodged by changing lane. Collect coins; speed rises with distance.
#define TR_ID 12
#define TR_N  10
struct TrObj { float d; int8_t lane; uint8_t t; };       // t: 0 barrier, 1 beam, 2 wall, 3 coin, 255 = unused
static TrObj trO[TR_N];
static float trX, trSp, trAcc; static int8_t trLane; static uint8_t trJ, trS; static uint16_t trCoins, trHi, trScore; static float trDist;
static bool trOver; static uint8_t trPhase;
static int trY(float d) { return 12 + (int)(46 * d * d); }
static int trLx(int lane, float d) { return 64 + (int)((lane - 1) * 36 * d); }
static void trSpawn(int8_t lane, uint8_t t) { for (uint8_t i = 0; i < TR_N; i++) if (trO[i].t == 255) { trO[i].d = 0.1f; trO[i].lane = lane; trO[i].t = t; return; } }
static void trInit() {
  for (uint8_t i = 0; i < TR_N; i++) trO[i].t = 255;
  trX = 1; trLane = 1; trJ = trS = 0; trSp = 0.011f; trAcc = 0; trCoins = 0; trScore = 0; trDist = 0; trOver = false; trHi = hiGet(TR_ID); trPhase = 0;
}
static void trRow() {                                       // one procedural row: obstacle(s) always leave a free lane
  uint8_t k = random(10); int8_t l = random(3);
  if (k < 3) trSpawn(l, 0); else if (k < 5) trSpawn(l, 1);
  else if (k < 7) { trSpawn(l, 2); if (random(2)) trSpawn((l + 1) % 3, 2); }
  else trSpawn(random(3), 3);   // coin
}
static void trEnd() { trOver = true; trScore = (uint16_t)(trDist / 4) + trCoins * 5; endRun(TR_ID, trScore, trHi); }
static void trUpdate() {
  if (trOver) { if (overKeys()) trInit(); return; }
  trPhase++; if (in.px < 0 && trLane > 0) { trLane--; sfx(SFX_MOVE); } if (in.px > 0 && trLane < 2) { trLane++; sfx(SFX_MOVE); }
  trX += (trLane - trX) * 0.35f;
  if (!trJ && !trS) { if (in.aP) { trJ = 1; sfx(SFX_JUMP); } else if (in.bP) { trS = 1; sfx(SFX_DUCK); } }
  if (trJ) { if (++trJ > 22) trJ = 0; }
  if (trS) { if (++trS > 18) trS = 0; }
  trSp = 0.011f + trDist * 0.0000045f; if (trSp > 0.03f) trSp = 0.03f;
  trDist += trSp * 100; trAcc += trSp;
  float gap = 0.30f - trSp * 4; if (gap < 0.16f) gap = 0.16f;
  if (trAcc >= gap) { trAcc = 0; trRow(); }
  int jh = trJ ? (int)(16 * 4 * trJ * (22 - trJ) / (22 * 22)) : 0;
  for (uint8_t i = 0; i < TR_N; i++) {
    TrObj &o = trO[i]; if (o.t == 255) continue;
    o.d += trSp; if (o.d > 1.12f) { o.t = 255; continue; }
    if (o.d < 0.9f || o.d > 1.02f || o.lane != trLane) continue;
    if (o.t == 3) { o.t = 255; trCoins++; fx(SFX_COIN, C_GOLD, 80); }
    else if ((o.t == 0 && jh < 7) || (o.t == 1 && !trS) || o.t == 2) { fx(SFX_HIT, C_BAD, 300); trEnd(); return; }
  }
}
static void trDraw() {
  char b[28]; u8g2.setFont(FONT_S); snprintf(b, sizeof b, "%um  C%u  HI %u", (unsigned)(trDist / 4), trCoins, trHi); textC(b, 7);
  for (int k = 0; k < 4; k++) { int xb = 10 + k * 36; u8g2.drawLine(64 + (xb - 64) / 6, 12, xb, 63); }   // lane lines to the vanishing point
  for (int k = 0; k < 5; k++) { float d = (k + (trPhase % 20) / 20.0f) / 5.0f; int y = trY(d), h = (int)(54 * d); if (d > 0.05f) u8g2.drawHLine(64 - h, y, 2 * h + 1); }
  for (uint8_t i = 0; i < TR_N; i++) {                      // far objects first (array order is spawn order)
    TrObj &o = trO[i]; if (o.t == 255) continue;
    int x = trLx(o.lane, o.d), y = trY(o.d), w = 3 + (int)(24 * o.d), h = 2 + (int)(18 * o.d);
    switch (o.t) {
      case 0: u8g2.drawBox(x - w / 2, y - h / 3, w, h / 3 + 1); break;                                   // low barrier
      case 1: u8g2.drawVLine(x - w / 2, y - h * 2, h * 2); u8g2.drawVLine(x + w / 2, y - h * 2, h * 2); u8g2.drawBox(x - w / 2, y - h * 2, w, 2 + h / 4); break;  // beam on posts
      case 2: u8g2.drawFrame(x - w / 2, y - h, w, h); u8g2.drawLine(x - w / 2, y - h, x + w / 2, y - 1); break;  // wall
      default: u8g2.drawDisc(x, y - h / 3, 1 + (int)(3 * o.d));                                          // coin
    }
  }
  int px = trLx(0, 1) + (int)(trX * 36), jh = trJ ? (int)(16 * 4 * trJ * (22 - trJ) / (22 * 22)) : 0, py = 60 - jh;
  if (trS) { u8g2.drawBox(px - 4, py - 4, 9, 4); u8g2.drawDisc(px + 4, py - 3, 2); }                      // sliding
  else { u8g2.drawDisc(px, py - 11, 2); u8g2.drawBox(px - 2, py - 8, 5, 6); int l = (trPhase >> 1) & 1; u8g2.drawVLine(px - 1 + l * 2, py - 2, 3); u8g2.drawVLine(px + 1 - l * 2, py - 2, 3); }
  if (jh) u8g2.drawHLine(px - 3, 61, 7);                                                                   // shadow
  if (trOver) overBox(trScore, trHi);
}
static void trIcon(int x, int y) {
  u8g2.drawLine(x + 16, y + 4, x + 2, y + 30); u8g2.drawLine(x + 16, y + 4, x + 30, y + 30);
  u8g2.drawDisc(x + 16, y + 14, 2); u8g2.drawBox(x + 14, y + 17, 5, 6); u8g2.drawBox(x + 4, y + 26, 10, 3); u8g2.drawDisc(x + 24, y + 22, 2);
}

#pragma once
// Breakout - 5 brick layouts that repeat harder. Stick L/R = paddle, A (or up) = launch. W = wide paddle, L = extra life.
#define BO_ID 6
#define BO_C  8
#define BO_R  5
static uint8_t boBr[BO_R][BO_C];
static float boBx, boBy, boVx, boVy, boPx;
static uint8_t boLives, boLvl, boLeft; static uint16_t boScore, boHi, boWide; static bool boLaunched, boOver;
struct BoC { float x, y; uint8_t t; bool on; };
static BoC boC[3];
static int boPw() { return boWide ? 32 : 20; }

static void boLoad(uint8_t lv) {
  boLeft = 0; uint8_t p = (lv - 1) % 5;
  for (uint8_t r = 0; r < BO_R; r++) for (uint8_t c = 0; c < BO_C; c++) {
    uint8_t h = 0;
    switch (p) {
      case 0: h = (r < 4) ? 1 : 0; break;
      case 1: h = ((r + c) & 1) ? 1 : 0; break;
      case 2: h = (r < 4 && c >= r && c < BO_C - r) ? 1 : 0; break;
      case 3: h = (c & 1) ? 0 : ((r < 2) ? 2 : 1); break;
      default: h = (r < 2) ? 2 : 1;
    }
    if (lv > 5 && h == 1 && ((r + c) % 3 == 0)) h = 2;
    boBr[r][c] = h; if (h) boLeft++;
  }
  for (uint8_t i = 0; i < 3; i++) boC[i].on = false;
  boLaunched = false;
}
static void boInit() {
  boLvl = 1; boLives = 3; boScore = 0; boWide = 0; boOver = false; boPx = 54; boHi = hiGet(BO_ID); boLoad(1);
}
static bool boBrick() {
  int cx = (int)(boBx + 1), cy = (int)(boBy + 1);
  if (cy < 10) return false;
  int row = (cy - 10) / 6, col = cx / 16;
  if (row >= BO_R || col < 0 || col >= BO_C) return false;
  uint8_t &h = boBr[row][col]; if (!h) return false;
  h--;
  if (h == 0) {
    boLeft--; boScore += 10; fx(SFX_COIN, C_ORANGE, 60);
    if (random(100) < 12) for (uint8_t i = 0; i < 3; i++) if (!boC[i].on) { boC[i] = {(float)(col * 16 + 5), (float)(10 + row * 6), (uint8_t)random(2), true}; break; }
  } else { boScore += 2; sfx(SFX_MOVE); }
  if (boLeft == 0) { boLvl++; bannerLevel(boLvl); fx(SFX_LEVEL, C_GOOD, 300); boLoad(boLvl); }
  return true;
}
static void boUpdate() {
  if (boOver) { if (overKeys()) boInit(); return; }
  if (boWide) boWide--;
  boPx += in.ax * 0.045f; int pw = boPw(); if (boPx < 0) boPx = 0; if (boPx > 128 - pw) boPx = 128 - pw;
  for (uint8_t i = 0; i < 3; i++) {
    if (!boC[i].on) continue;
    boC[i].y += 1.0f; if (boC[i].y > 64) { boC[i].on = false; continue; }
    if (hitBox(boC[i].x, boC[i].y, 6, 5, boPx, 60, pw, 3)) {
      boC[i].on = false;
      if (boC[i].t == 0) boWide = 600; else if (boLives < 5) boLives++;
      fx(SFX_POWER, C_GOOD, 150);
    }
  }
  if (!boLaunched) {
    boBx = boPx + pw / 2 - 1; boBy = 57;
    if (in.aP || in.py < 0) {
      boLaunched = true; boVx = random(2) ? 1.2f : -1.2f;
      float s = 1.8f + 0.15f * boLvl; if (s > 3.2f) s = 3.2f; boVy = -s; sfx(SFX_JUMP);
    }
    return;
  }
  boBx += boVx;
  if (boBx < 0) { boBx = 0; boVx = -boVx; } if (boBx > 126) { boBx = 126; boVx = -boVx; }
  if (boBrick()) boVx = -boVx;
  boBy += boVy; if (boBy < 8) { boBy = 8; boVy = -boVy; }
  if (boBrick()) boVy = -boVy;
  if (boLaunched && boVy > 0 && boBy + 2 >= 60 && boBy <= 62 && boBx + 2 >= boPx && boBx <= boPx + pw) {
    float sp = fabsf(boVy) * 1.03f; if (sp > 3.4f) sp = 3.4f;
    boVy = -sp; boBy = 57.5f; boVx = ((boBx + 1) - (boPx + pw / 2.0f)) / (pw / 2.0f) * 2.4f; sfx(SFX_SELECT);
  }
  if (boBy > 64) {
    boLives--; fx(SFX_HIT, C_BAD, 250); boLaunched = false;
    if (boLives == 0) { boOver = true; endRun(BO_ID, boScore, boHi); }
  }
}
static void boDraw() {
  char b[28]; u8g2.setFont(FONT_S);
  snprintf(b, sizeof b, "L%u LV%u %u HI %u", boLives, boLvl, boScore, boHi); u8g2.drawStr(1, 7, b);
  for (uint8_t r = 0; r < BO_R; r++) for (uint8_t c = 0; c < BO_C; c++) if (boBr[r][c]) {
    u8g2.drawBox(c * 16 + 1, 10 + r * 6, 14, 4);
    if (boBr[r][c] == 1 && boLvl >= 1) { u8g2.setDrawColor(0); u8g2.drawHLine(c * 16 + 3, 11 + r * 6, 10); u8g2.setDrawColor(1); }
  }
  for (uint8_t i = 0; i < 3; i++) if (boC[i].on) { u8g2.drawFrame((int)boC[i].x, (int)boC[i].y, 7, 6); u8g2.drawPixel((int)boC[i].x + 3, (int)boC[i].y + 2); u8g2.drawPixel((int)boC[i].x + (boC[i].t ? 2 : 4), (int)boC[i].y + 3); }
  u8g2.drawBox((int)boPx, 60, boPw(), 3); u8g2.drawBox((int)boBx, (int)boBy, 2, 2);
  if (!boLaunched && !boOver) { u8g2.setFont(FONT_S); textC("A: launch", 52); }
  if (boOver) overBox(boScore, boHi);
}
static void boIcon(int x, int y) {
  for (int r = 0; r < 3; r++) for (int c = 0; c < 4; c++) u8g2.drawBox(x + c * 8, y + 3 + r * 5, 7, 3);
  u8g2.drawBox(x + 8, y + 27, 14, 3); u8g2.drawBox(x + 20, y + 19, 2, 2);
}

