#pragma once
// Road Racer - 4 lanes. Stick up/down = change lane, A = nitro, B = brake. Grab coins to refill nitro.
#define RC_ID 3
#define RC_N  7
struct RcV { float x, v; uint8_t lane, w, t; bool on; };   // t: 0 car, 1 truck, 2 coin
static RcV rV[RC_N];
static float rY, rSpd, rDist, rNitro, rOff;
static uint8_t rLane, rLevel; static uint16_t rScore, rHi, rCoins; static int16_t rCd; static bool rDead;
static inline int rLaneTop(uint8_t l) { return 8 + l * 14; }

static void rcInit() {
  rLane = 2; rY = rLaneTop(2) + 3; rSpd = 2.0f; rDist = 0; rNitro = 60; rOff = 0; rLevel = 1;
  rScore = 0; rCoins = 0; rCd = 40; rDead = false; rHi = hiGet(RC_ID);
  for (uint8_t i = 0; i < RC_N; i++) rV[i].on = false;
}
static void rcSpawn() {
  uint8_t lane = random(4); int busy = 0; bool laneBusy = false;
  for (uint8_t i = 0; i < RC_N; i++) if (rV[i].on && rV[i].x > 84) { busy++; if (rV[i].lane == lane) laneBusy = true; }
  bool coin = random(100) < 14;
  if (laneBusy || (!coin && busy >= 3)) return;
  for (uint8_t i = 0; i < RC_N; i++) if (!rV[i].on) {
    RcV &c = rV[i]; c.on = true; c.x = 128; c.lane = lane;
    if (coin) { c.t = 2; c.w = 6; c.v = 0; }
    else if (rLevel >= 2 && random(100) < 22) { c.t = 1; c.w = 26; c.v = 0.6f; }
    else { c.t = 0; c.w = 14; c.v = 0.8f + random(0, 8) / 10.0f; }
    return;
  }
}
static void rcUpdate() {
  if (rDead) { if (overKeys()) rcInit(); return; }
  if (in.py < 0 && rLane > 0) { rLane--; sfx(SFX_MOVE); }
  if (in.py > 0 && rLane < 3) { rLane++; sfx(SFX_MOVE); }
  float ty = rLaneTop(rLane) + 3;
  if (rY < ty) { rY += 3; if (rY > ty) rY = ty; } else if (rY > ty) { rY -= 3; if (rY < ty) rY = ty; }
  float base = 2.0f + rLevel * 0.3f; if (base > 5.5f) base = 5.5f; float tgt = base;
  bool boost = in.a && rNitro > 1;
  if (boost) { tgt = base + 2.2f; rNitro -= 1.0f; if (rNitro < 0) rNitro = 0; ledFlash(C_PURPLE, 60); }
  else { if (in.b) tgt = base - 1.0f < 1.0f ? 1.0f : base - 1.0f; rNitro += 0.12f; if (rNitro > 100) rNitro = 100; }
  rSpd += (tgt - rSpd) * 0.2f;
  rDist += rSpd * 0.08f * (boost ? 1.5f : 1.0f);
  uint8_t nl = 1 + (uint16_t)(rDist / 120);
  if (nl > rLevel) { rLevel = nl; bannerLevel(nl); fx(SFX_LEVEL, C_CYAN, 200); }
  rScore = (uint16_t)rDist + rCoins * 10;
  rOff += rSpd; if (rOff >= 16) rOff -= 16;
  if (--rCd <= 0) { rcSpawn(); rCd = (int)(random(20, 46) * 3.0f / (rSpd + 1.0f)); if (rCd < 8) rCd = 8; }
  for (uint8_t i = 0; i < RC_N; i++) {
    RcV &c = rV[i]; if (!c.on) continue;
    float sp = (c.t == 2) ? rSpd : (rSpd - c.v < 0.5f ? 0.5f : rSpd - c.v);
    c.x -= sp; if (c.x + c.w < 0) { c.on = false; continue; }
    float cy = rLaneTop(c.lane) + 3;
    if (hitBox(15, rY + 1, 12, 6, c.x + 1, cy + 1, c.w - 2, 6)) {
      if (c.t == 2) { c.on = false; rCoins++; rNitro += 25; if (rNitro > 100) rNitro = 100; fx(SFX_COIN, C_GOLD, 100); }
      else { rDead = true; endRun(RC_ID, rScore, rHi); }
    }
  }
}
static void rcDraw() {
  u8g2.drawHLine(0, 8, 128); u8g2.drawHLine(0, 63, 128);
  for (int l = 1; l < 4; l++) for (int x = -(int)rOff; x < 128; x += 16) u8g2.drawHLine(x, 8 + l * 14, 8);
  for (uint8_t i = 0; i < RC_N; i++) {
    if (!rV[i].on) continue;
    int x = (int)rV[i].x, y = rLaneTop(rV[i].lane) + 3, w = rV[i].w;
    if (rV[i].t == 2) u8g2.drawDisc(x + 3, y + 4, 3);
    else {
      u8g2.drawFrame(x, y, w, 8);
      if (rV[i].t == 1) { u8g2.drawVLine(x + w - 8, y, 8); u8g2.drawBox(x + w - 6, y + 2, 4, 4); }
      else u8g2.drawBox(x + 3, y + 2, 4, 4);
    }
  }
  int py = (int)rY;
  u8g2.drawBox(14, py, 14, 8); u8g2.setDrawColor(0); u8g2.drawBox(21, py + 1, 3, 6); u8g2.drawVLine(17, py + 2, 4); u8g2.setDrawColor(1);
  if (in.a && rNitro > 1) { u8g2.drawBox(8, py + 2, 5, 1); u8g2.drawBox(5, py + 5, 8, 1); }
  char b[24]; u8g2.setFont(FONT_S);
  snprintf(b, sizeof b, "%05u LV%u", rScore, rLevel); u8g2.drawStr(1, 7, b);
  u8g2.drawStr(78, 7, "N"); u8g2.drawFrame(85, 1, 40, 6); u8g2.drawBox(86, 2, (int)(rNitro * 0.38f), 4);
  if (rDead) overBox(rScore, rHi);
}
static void rcIcon(int x, int y) {
  u8g2.drawHLine(x, y + 6, 32); u8g2.drawHLine(x, y + 26, 32);
  for (int i = 0; i < 32; i += 8) u8g2.drawHLine(x + i, y + 16, 4);
  u8g2.drawBox(x + 3, y + 18, 12, 6); u8g2.setDrawColor(0); u8g2.drawBox(x + 9, y + 19, 3, 4); u8g2.setDrawColor(1);
  u8g2.drawFrame(x + 18, y + 8, 12, 6);
}

#include <Arduino.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>

// Logical 128x64 drawing API compatibility layer for the original ARCADE-C3.
// Landscape TFT canvas: 320x240, game area scaled 2.5x and vertically centered.
#define TFT_PIN_CS   10
#define TFT_PIN_DC   9
#define TFT_PIN_RST  8
#define TFT_PIN_BL   7
#define TFT_PIN_SCLK 12
#define TFT_PIN_MOSI 11

class ArcadeTFTCompat {
  Adafruit_ST7789 tft;
  uint16_t ink = 0xF81F; // vivid pink foreground
  uint8_t fontSize = 2;
  uint8_t logicalCharWidth = 5;
  static constexpr float S = 2.5f;
  static int X(int x) { return (int)lroundf(x * S); }
  static int Y(int y) { return 40 + (int)lroundf(y * S); }
  static int W(int w) { return (int)lroundf(w * S); }
  static int H(int h) { return (int)lroundf(h * S); }
public:
  ArcadeTFTCompat() : tft(TFT_PIN_CS, TFT_PIN_DC, TFT_PIN_RST) {}
  void begin() {
    SPI.begin(TFT_PIN_SCLK, -1, TFT_PIN_MOSI, TFT_PIN_CS);
    tft.init(240, 320);
    tft.setRotation(1); // 320x240 landscape
    tft.fillScreen(0x2108);
    pinMode(TFT_PIN_BL, OUTPUT);
    setBrightness(75);
  }
  void setBrightness(uint8_t percent) {
    if (percent > 100) percent = 100;
    analogWrite(TFT_PIN_BL, (uint16_t)percent * 255 / 100);
  }
  void setBusClock(uint32_t) {}
  void clearBuffer() { tft.fillScreen(0x2108); }
  void sendBuffer() {}
  void setDrawColor(uint8_t c) {
    // U8g2 draw colour 0 = erase/background, 1 = draw, 2 = highlight.
    ink = (c == 0) ? 0x2108 : ((c == 2) ? 0xFBBF : 0xF81F);
  }
  void setFont(const uint8_t *f) {
    // Adafruit's built-in font is not a pixel-perfect U8g2 replacement.
    // Keep HUD text compact; only the large boot wordmark uses 3x text.
    fontSize = (f == u8g2_font_helvB14_tf) ? 3 : 2;
    logicalCharWidth = (f == u8g2_font_5x7_tf) ? 5 : ((fontSize == 3) ? 7 : 6);
  }
  int getStrWidth(const char *s) const { return (int)strlen(s) * logicalCharWidth; }
  void drawStr(int x, int y, const char *s) {
    tft.setTextWrap(false); tft.setTextColor(ink); // transparent text; preserve pink panels underneath
    tft.setTextSize(fontSize);
    tft.setCursor(X(x), Y(y) - (fontSize == 2 ? 16 : 24)); tft.print(s);
  }
  void drawPixel(int x,int y) { tft.drawPixel(X(x),Y(y),ink); }
  void drawBox(int x,int y,int w,int h) { if(w>0&&h>0)tft.fillRect(X(x),Y(y),max(1,W(w)),max(1,H(h)),ink); }
  void drawFrame(int x,int y,int w,int h) { if(w>0&&h>0)tft.drawRect(X(x),Y(y),max(1,W(w)),max(1,H(h)),ink); }
  void drawHLine(int x,int y,int w) { if(w>0)tft.drawFastHLine(X(x),Y(y),max(1,W(w)),ink); }
  void drawVLine(int x,int y,int h) { if(h>0)tft.drawFastVLine(X(x),Y(y),max(1,H(h)),ink); }
  void drawLine(int x0,int y0,int x1,int y1) { tft.drawLine(X(x0),Y(y0),X(x1),Y(y1),ink); }
  void drawCircle(int x,int y,int r) { tft.drawCircle(X(x),Y(y),max(1,W(r)),ink); }
  void drawDisc(int x,int y,int r) { tft.fillCircle(X(x),Y(y),max(1,W(r)),ink); }
  void drawRBox(int x,int y,int w,int h,int r) { if(w>0&&h>0)tft.fillRoundRect(X(x),Y(y),max(1,W(w)),max(1,H(h)),max(1,W(r)),ink); }
  void drawRFrame(int x,int y,int w,int h,int r) { if(w>0&&h>0)tft.drawRoundRect(X(x),Y(y),max(1,W(w)),max(1,H(h)),max(1,W(r)),ink); }
  void drawTriangle(int x0,int y0,int x1,int y1,int x2,int y2) { tft.fillTriangle(X(x0),Y(y0),X(x1),Y(y1),X(x2),Y(y2),ink); }
};

#pragma once
// Snake - levels every 6 foods: faster + more rocks. Bonus star every 5th food (timed, worth 3).
#define SN_ID     5
#define SN_CW     32
#define SN_CH     14
#define SN_MAX    (SN_CW * SN_CH)
#define SN_STONES 24
static uint8_t snX[SN_MAX], snY[SN_MAX], stX[SN_STONES], stY[SN_STONES];
static uint16_t snLen, snScore, snHi, snEat; static uint8_t snStn, snLvl, snFx, snFy, snBx, snBy;
static int8_t snDx, snDy, snNx, snNy; static int16_t snBt; static bool snDead; static uint32_t snLast;

static bool snOcc(uint8_t x, uint8_t y) {
  for (uint16_t i = 0; i < snLen; i++) if (snX[i] == x && snY[i] == y) return true;
  for (uint8_t i = 0; i < snStn; i++) if (stX[i] == x && stY[i] == y) return true;
  return (x == snFx && y == snFy) || (snBt > 0 && x == snBx && y == snBy);
}
static void snPlace(uint8_t &ox, uint8_t &oy) {   // pick into temporaries: ox/oy may alias snFx/snBx
  uint8_t x, y; do { x = random(SN_CW); y = random(SN_CH); } while (snOcc(x, y)); ox = x; oy = y;
}
static void snInit() {
  snLen = 3; for (uint8_t i = 0; i < 3; i++) { snX[i] = 16 - i; snY[i] = 7; }
  snDx = snNx = 1; snDy = snNy = 0; snScore = 0; snEat = 0; snLvl = 1; snStn = 0; snBt = 0; snDead = false;
  snLast = millis(); snHi = hiGet(SN_ID); snFx = 255; snFy = 255; snPlace(snFx, snFy);
}
static void snAddStones() {
  for (uint8_t k = 0; k < 3 && snStn < SN_STONES; k++)
    for (uint8_t t = 0; t < 40; t++) {
      uint8_t x = random(SN_CW), y = random(SN_CH);
      if (abs((int)x - snX[0]) + abs((int)y - snY[0]) < 6 || snOcc(x, y)) continue;
      stX[snStn] = x; stY[snStn] = y; snStn++; break;
    }
}
static void snDie() { snDead = true; endRun(SN_ID, snScore, snHi); }
static void snUpdate() {
  if (snDead) { if (overKeys()) snInit(); return; }
  if (in.dx && snDx == 0) { snNx = in.dx; snNy = 0; } else if (in.dy && snDy == 0) { snNx = 0; snNy = in.dy; }
  if (snBt > 0) snBt--;
  uint32_t iv = (snLvl >= 10) ? 55 : (140 - snLvl * 9);
  if (millis() - snLast < iv) return;
  snLast = millis(); snDx = snNx; snDy = snNy;
  int nx = snX[0] + snDx, ny = snY[0] + snDy;
  if (nx < 0 || ny < 0 || nx >= SN_CW || ny >= SN_CH) { snDie(); return; }
  for (uint8_t i = 0; i < snStn; i++) if (stX[i] == nx && stY[i] == ny) { snDie(); return; }
  bool food = (nx == snFx && ny == snFy), bonus = (snBt > 0 && nx == snBx && ny == snBy), grow = food || bonus;
  uint16_t lim = grow ? snLen : snLen - 1;
