#pragma once
// Sliding 8-puzzle. Joystick moves the selection; A swaps with the blank.
#define PUZZLE_ID 26
static uint8_t pzBoard[9], pzCursor = 0;
static uint16_t pzMoves = 0;
static bool pzSolved = false;
static uint32_t pzLock = 0;
static void pzInit() {
  for (uint8_t i = 0; i < 9; ++i) pzBoard[i] = (i + 1) % 9;
  // Shuffle by legal moves so the board is always solvable.
  uint8_t blank = 8;
  for (uint16_t i = 0; i < 80; ++i) {
    uint8_t opts[4], n = 0;
    if (blank % 3) opts[n++] = blank - 1;
    if (blank % 3 < 2) opts[n++] = blank + 1;
    if (blank >= 3) opts[n++] = blank - 3;
    if (blank < 6) opts[n++] = blank + 3;
    uint8_t j = opts[random(n)];
    pzBoard[blank] = pzBoard[j]; pzBoard[j] = 0; blank = j;
  }
  pzCursor = blank; pzMoves = 0; pzSolved = false; pzLock = millis() + 150;
}
static bool pzCheckSolved() {
  for (uint8_t i = 0; i < 8; ++i) if (pzBoard[i] != i + 1) return false;
  return pzBoard[8] == 0;
}
static void pzUpdate() {
  if (pzSolved) { if (overKeys()) pzInit(); return; }
  if ((int32_t)(millis() - pzLock) < 0) return;
  int8_t d = in.rx ? in.rx : in.ry;
  if (d) {
    int x = pzCursor % 3, y = pzCursor / 3;
    if (in.rx < 0 && x > 0) --x;
    else if (in.rx > 0 && x < 2) ++x;
    else if (in.ry < 0 && y > 0) --y;
    else if (in.ry > 0 && y < 2) ++y;
    pzCursor = y * 3 + x; pzLock = millis() + 130;
  }
  if (in.aP) {
    int x = pzCursor % 3, y = pzCursor / 3, blank = -1;
    if (x > 0 && pzBoard[pzCursor - 1] == 0) blank = pzCursor - 1;
    if (x < 2 && pzBoard[pzCursor + 1] == 0) blank = pzCursor + 1;
    if (y > 0 && pzBoard[pzCursor - 3] == 0) blank = pzCursor - 3;
    if (y < 2 && pzBoard[pzCursor + 3] == 0) blank = pzCursor + 3;
    if (blank >= 0) {
      pzBoard[blank] = pzBoard[pzCursor]; pzBoard[pzCursor] = 0;
      pzCursor = blank; ++pzMoves; pzSolved = pzCheckSolved(); pzLock = millis() + 130;
      if (pzSolved) { endRun(PUZZLE_ID, pzMoves, hiGet(PUZZLE_ID)); fx(SFX_LEVEL, C_GOOD, 300); }
    }
  }
}
static void pzDraw() {
  char b[24]; u8g2.setFont(FONT_S); snprintf(b, sizeof b, "SLIDE PUZZLE %u", pzMoves); textC(b, 7);
  for (uint8_t i = 0; i < 9; ++i) {
    int x = 25 + (i % 3) * 27, y = 12 + (i / 3) * 15;
    if (pzBoard[i]) { u8g2.drawFrame(x, y, 23, 12); char n[3]; snprintf(n, sizeof n, "%u", pzBoard[i]); int w = u8g2.getStrWidth(n); u8g2.drawStr(x + (23 - w) / 2, y + 9, n); }
    else u8g2.drawFrame(x, y, 23, 12);
    if (i == pzCursor) u8g2.drawFrame(x - 2, y - 2, 27, 16);
  }
  if (pzSolved) { u8g2.setFont(FONT_M); textC("SOLVED! A:AGAIN", 60); }
}
static void pzIcon(int x, int y) {
  for (int i = 0; i < 9; ++i) { int xx = x + 3 + (i % 3) * 9, yy = y + 3 + (i / 3) * 9; u8g2.drawFrame(xx, yy, 7, 7); if (i < 8) { char n[2] = {(char)('1' + i), 0}; u8g2.drawStr(xx + 2, yy + 6, n); } }
}

