static int8_t ttCheck(){const uint8_t l[8][3]={{0,1,2},{3,4,5},{6,7,8},{0,3,6},{1,4,7},{2,5,8},{0,4,8},{2,4,6}};for(int i=0;i<8;i++)if(ttBoard[l[i][0]]&&ttBoard[l[i][0]]==ttBoard[l[i][1]]&&ttBoard[l[i][1]]==ttBoard[l[i][2]])return ttBoard[l[i][0]];for(int i=0;i<9;i++)if(!ttBoard[i])return 0;return 3;}
